// Normaliza el webhook para que el resto del flujo reciba siempre { dealId }.
// Soporta:
// 1) { body: { dealId: 123 } }
// 2) payload antiguo con la clave accidental "dealId "
// 3) webhook nativo de Pipedrive con body.current.id

const input = $input.first().json || {};
const body = input.body ?? input;
const current = body.current ?? body.data?.current ?? null;

const candidates = [
  body.dealId,
  body['dealId '],
  body.deal_id,
  current?.id,
  body.data?.id,
];

let dealId = null;
for (const candidate of candidates) {
  if (candidate === undefined || candidate === null || candidate === '') continue;
  const parsed = Number.parseInt(String(candidate).trim(), 10);
  if (Number.isFinite(parsed) && parsed > 0) {
    dealId = parsed;
    break;
  }
}

if (!dealId) {
  throw new Error('No se encontró un dealId válido en el webhook. Esperado body.dealId o body.current.id.');
}

return [{
  json: {
    dealId,
    triggerStageId: current?.stage_id ?? null,
    triggerPipelineId: current?.pipeline_id ?? null,
  },
}];

// Detectar si Bank 1–5 contiene Kutxabank, localizar el bank deal y preparar contexto.
// Kutxabank option IDs: 2633 (B1), 2651 (B2), 2669 (B3), 2687 (B4), 2705 (B5)

const deal = $input.first().json;

const KUTXA_OPTION_IDS = [2633, 2651, 2669, 2687, 2705];
const BANK_FIELD_IDS = [
  'af536dbfe7d00fd441ae9bd4b144c25bc1d4c725',
  '8e4b44a3f3973d1f524f8cd0ec6f6babe9e96965',
  'ed0a30972778ac2c3d29cab53e27a89f5b52a1b2',
  '9049591570e78d3274a72cfb7a28076789ce0676',
  '36ff3525fb8a73637e069099967b2afe164e408a',
];
const BANK_ID_FIELD_IDS = [
  '04d666f12e4d27a3867daa5d7d6b777d76d24eb9',
  '75d8963d89d47daf37349722c531677263173484',
  '874add027adde7fa7690874e3bac581489387651',
  '467feaa56488620159ef39890e6d8f96489bdbac',
  'b3dfef96dce320a1cfa4605056757f7e79731676',
];
const BANK_LINK_FIELD_IDS = [
  'fc8312a76b8fe194ba55b60f3e09ac7e7800a5bd',
  'd78cdb37e370d21facdea787f4bd7a22520ac62d',
  'b3b1fd8fba90a455d01fb4aa4805569d4b60070a',
  '9a4d771432722d30f6e4abe8f0cee6a542793475',
  '963244c4d383295066674c693d813b4abb27ae11',
];

function rawScalar(raw) {
  if (raw === null || raw === undefined) return '';
  if (typeof raw !== 'object') return raw;
  return raw.id ?? raw.value ?? raw.label ?? raw.name ?? raw.url ?? '';
}

function parseBankDealId(raw) {
  if (raw == null) return null;
  const scalar = rawScalar(raw);
  const str = String(scalar).trim();
  if (!str) return null;
  if (/^\d+$/.test(str)) {
    const id = Number.parseInt(str, 10);
    return id > 0 ? id : null;
  }
  const m = str.match(/\/deal\/(\d+)/i) || str.match(/[?&](?:deal_?id|id)=(\d+)/i);
  if (!m) return null;
  const id = Number.parseInt(m[1], 10);
  return Number.isFinite(id) && id > 0 ? id : null;
}

function parseDriveFolderId(raw) {
  const str = String(raw ?? '').trim();
  if (!str) return null;
  const folderMatch = str.match(/\/folders\/([a-zA-Z0-9_-]+)/i);
  if (folderMatch) return folderMatch[1];
  const idMatch = str.match(/[?&]id=([a-zA-Z0-9_-]+)/i);
  if (idMatch) return idMatch[1];
  if (/^[a-zA-Z0-9_-]{10,}$/.test(str)) return str;
  return null;
}

function enumId(raw) {
  const scalar = rawScalar(raw);
  const n = Number.parseInt(String(scalar).trim(), 10);
  return Number.isFinite(n) ? n : null;
}

function enumLabel(raw) {
  if (raw && typeof raw === 'object') {
    const label = raw.label ?? raw.name ?? raw.value;
    if (label !== undefined && label !== null && !/^\d+$/.test(String(label).trim())) return String(label);
  }
  const str = String(raw ?? '').trim();
  return /^\d+$/.test(str) ? '' : str;
}

const contractType1Map = {
  2613: 'Indefinido', 2614: 'Funcionario', 2615: 'Autónomo', 2616: 'Temporal',
  2617: 'Interino', 2618: 'Fijo discontínuo', 2619: 'Desempleado',
  2620: 'Jubilado', 2863: 'Pensionista'
};
const contractType2Map = {
  2526: 'Indefinido', 2527: 'Funcionario', 2528: 'Autónomo', 2529: 'Temporal',
  2530: 'Desempleado', 2531: 'Interino', 2532: 'Fijo discontínuo', 2864: 'Pensionista'
};
function resolveEnum(rawValue, map) {
  if (rawValue === null || rawValue === undefined || rawValue === '') return '';
  const id = enumId(rawValue);
  if (id !== null && map[id]) return map[id];
  return enumLabel(rawValue) || String(rawScalar(rawValue));
}

let kutxaSlot = -1;
for (let i = 0; i < BANK_FIELD_IDS.length; i++) {
  const raw = deal[BANK_FIELD_IDS[i]];
  const id = enumId(raw);
  const label = enumLabel(raw).toLowerCase();
  if (id === KUTXA_OPTION_IDS[i] || label.includes('kutxabank')) {
    kutxaSlot = i;
    break;
  }
}

if (kutxaSlot === -1) {
  return [{ json: { isKutxa: false, reason: 'Kutxabank no está en Bank 1–5', dealId: deal.id } }];
}

const bankDealId =
  parseBankDealId(deal[BANK_ID_FIELD_IDS[kutxaSlot]]) ??
  parseBankDealId(deal[BANK_LINK_FIELD_IDS[kutxaSlot]]);

const driveUrl = deal['c2ea08d72de437ee4957ff3807c48cebe7a1aa3e'] || '';
const folderId = parseDriveFolderId(driveUrl);
const dni = String(deal['60228dc43313b931378ec9bb3f21f7ad7f5a144c'] || '').trim();
const plan = deal['b5d36c005e38a4cd72d831be655996a3d6b34dc1'] || '';
const nombreCliente = deal.person_name || '';
const secondTitular = deal['209a0da7966a29bf05e96b6a124536222e0318dd'] || '';

const requiredMissing = [];
if (!bankDealId) requiredMissing.push('bankDealId');
if (!folderId) requiredMissing.push('folderId');
if (!dni) requiredMissing.push('dni');
if (requiredMissing.length) {
  throw new Error(`Kutxabank detectado, pero faltan datos obligatorios: ${requiredMissing.join(', ')}`);
}

const importeCompraventa = deal['184fc13001dbca74b20c77f0fcfdec161b5cb492'] || '';
const importeHipoteca = deal['b80d8ee37cc14ecdd7d8a640a57d6bd85308d5b9'] || '';
const ingresos1T = deal['8e0e7ac2bd665bc3c0c5eb7d979a1ae1d9bc1300'] || '';
const contrato1T = resolveEnum(deal['5788be4f764dabff9006ab5d685ae8061c7db3d9'], contractType1Map);
const ingresos2T = deal['a52a8dcf3e016ffd7e670c6d888d30b4f08dc895'] || '';
const contrato2T = resolveEnum(deal['9d6bb0a4cffae14651df0370331afa40b101c6e9'], contractType2Map);

return [{
  json: {
    isKutxa: true,
    dealId: deal.id,
    bankDealId,
    folderId,
    driveUrl,
    dni,
    plan,
    nombreCliente,
    hasSecondTitular: Boolean(secondTitular),
    kutxaSlot,
    importeCompraventa,
    importeHipoteca,
    ingresos1T,
    contrato1T,
    ingresos2T,
    contrato2T,
  }
}];

// Selecciona C003–C008, F016, autorizaciones Kutxabank/Bayteca
// y, si hay segundo titular, también D003–D008.
const info = $('Detectar Kutxabank').first().json;

// Archivos de la carpeta del deal
const folderFiles = $('Listar archivos Drive').first().json.files || [];

// Autorizaciones buscadas en todo Drive
function getFilesFromExecutedNode(nodeName) {
  try {
    return $(nodeName).first().json.files || [];
  } catch (e) {
    return [];
  }
}

// La autorización Kutxabank puede aparecer en cualquiera de los 3 intentos.
const authKutxaFiles = [
  ...getFilesFromExecutedNode('FindAuthKutxabank'),
  ...getFilesFromExecutedNode('FindAuthKutxabank Retry 2'),
  ...getFilesFromExecutedNode('FindAuthKutxabank Retry 3'),
];
const authBaytecaFiles = $('FindAuthBayteca').first().json.files || [];

// Merge all files into one list
const allFiles = [...folderFiles, ...authKutxaFiles, ...authBaytecaFiles];

const DOC_CODES_1T = ['C003', 'C004', 'C005', 'C006', 'C007', 'C008'];
const DOC_CODES_2T = ['D003', 'D004', 'D005', 'D006', 'D007', 'D008'];
const EXTRA_CODES = ['F016']; // Otros

// Build needed codes: always 1T + F016; add 2T only if second titular exists
const neededCodes = [...DOC_CODES_1T, ...EXTRA_CODES];
if (info.hasSecondTitular) {
  neededCodes.push(...DOC_CODES_2T);
}
// Auth docs tracked separately
const AUTH_DOCS = ['AUTH_KUTXABANK', 'AUTH_BAYTECA'];


// Ensure filename has proper extension based on mimeType
function ensureExtension(name, mimeType) {
  // If name already has a common extension, keep it
  if (/\.(pdf|jpg|jpeg|png|doc|docx|xls|xlsx|zip|txt|csv|xml)$/i.test(name)) return name;
  const extMap = {
    'application/pdf': '.pdf',
    'image/jpeg': '.jpg',
    'image/png': '.png',
    'image/gif': '.gif',
    'image/webp': '.webp',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document': '.docx',
    'application/msword': '.doc',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': '.xlsx',
    'application/vnd.ms-excel': '.xls',
    'text/plain': '.txt',
    'text/csv': '.csv',
  };
  const ext = extMap[mimeType] || '.pdf'; // default to .pdf for docs
  return name + ext;
}

// code -> array de archivos. Un mismo código puede tener varios archivos
// (p.ej. C003 anverso + reverso, varias nóminas): se incluyen TODOS.
const foundFiles = {};
const seenIds = new Set(); // un archivo que coincide con 2 códigos solo entra una vez
const matchedCodes = new Set(); // códigos cubiertos (aunque el archivo ya esté incluido por otro código)

// Orden estable por nombre para que el ZIP sea reproducible
const sortedFolderFiles = [...folderFiles].sort((a, b) =>
  String(a.name || '').localeCompare(String(b.name || '')));

// Match C/D/F codes from folder files
for (const file of sortedFolderFiles) {
  const fileName = String(file.name || '');
  if (/\.zip$/i.test(fileName)) continue; // nunca meter un ZIP previo dentro del ZIP
  const upper = fileName.toUpperCase();
  for (const code of neededCodes) {
    const re = new RegExp(`(^|[^A-Z0-9])${code}([^A-Z0-9]|$)`, 'i');
    if (!re.test(upper)) continue;
    matchedCodes.add(code);
    if (!seenIds.has(file.id)) {
      (foundFiles[code] = foundFiles[code] || []).push({ id: file.id, name: ensureExtension(fileName, file.mimeType || ''), mimeType: file.mimeType || '' });
      seenIds.add(file.id);
    }
  }
}

// Auth Kutxabank (1 archivo)
if (authKutxaFiles.length > 0) {
  const f = authKutxaFiles[0];
  foundFiles['AUTH_KUTXABANK'] = [{ id: f.id, name: ensureExtension(f.name, f.mimeType || ''), mimeType: f.mimeType || '' }];
}

// Auth Bayteca (1 archivo)
if (authBaytecaFiles.length > 0) {
  const f = authBaytecaFiles[0];
  foundFiles['AUTH_BAYTECA'] = [{ id: f.id, name: ensureExtension(f.name, f.mimeType || ''), mimeType: f.mimeType || '' }];
}

// All expected docs
const allExpected = [...neededCodes, ...AUTH_DOCS];
const missingDocs = allExpected.filter(code => !matchedCodes.has(code) && !(foundFiles[code] && foundFiles[code].length));
const filesToDownload = allExpected.flatMap(code => foundFiles[code] || []);

if (filesToDownload.length === 0) {
  throw new Error(`No se encontró ningún documento para Kutxabank en la carpeta ${info.folderId}. Faltan: ${missingDocs.join(', ')}`);
}

const safeClient = String(info.nombreCliente || 'Cliente')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-zA-Z0-9_-]+/g, '_')
  .replace(/^_+|_+$/g, '') || 'Cliente';
const safeDni = String(info.dni).replace(/[^a-zA-Z0-9_-]+/g, '');
const zipFilename = `Kutxabank_${info.bankDealId}_${safeClient}_${safeDni}.zip`;

// --- Dedup: check if ZIP already exists in folder ---
const existingZip = folderFiles.find(f => {
  const nm = String(f.name || '').toLowerCase();
  return nm === zipFilename.toLowerCase() || (nm.endsWith('.zip') && nm.includes(String(info.bankDealId)));
});
const zipAlreadyExists = Boolean(existingZip);
const existingZipFileId = existingZip ? existingZip.id : '';
const existingZipDriveLink = existingZipFileId
  ? 'https://drive.google.com/file/d/' + existingZipFileId + '/view'
  : '';

return filesToDownload.map((f, idx) => ({
  json: {
    ...info,
    fileId: f.id,
    fileName: f.name,
    fileMimeType: f.mimeType,
    isLastFile: idx === filesToDownload.length - 1,
    totalFiles: filesToDownload.length,
    missingDocs,
    zipFilename,
    zipAlreadyExists,
    existingZipFileId,
    existingZipDriveLink,
  }
}));

// Crea un ZIP protegido con contraseña = DNI directamente dentro de n8n.
// --- Dedup: skip ZIP creation if already exists in Drive ---
const firstSource = $('Filtrar documentos C/D').first().json;
if (firstSource.zipAlreadyExists) {
  const ctx = firstSource;
  return [{
    json: {
      dealId: ctx.dealId,
      bankDealId: ctx.bankDealId,
      folderId: ctx.folderId,
      zipFilename: ctx.zipFilename,
      nombreCliente: ctx.nombreCliente,
      dni: ctx.dni,
      plan: ctx.plan,
      missingDocs: ctx.missingDocs || [],
      fileCount: 0,
      includedFiles: [],
      totalSourceBytes: 0,
      zipSizeBytes: 0,
      zipCreated: false,
      zipAlreadyExists: true,
      existingZipFileId: ctx.existingZipFileId,
      existingZipDriveLink: ctx.existingZipDriveLink,
      zipEncryption: 'ZipCrypto',
      zipCompression: 'STORE',
      importeCompraventa: ctx.importeCompraventa,
      importeHipoteca: ctx.importeHipoteca,
      ingresos1T: ctx.ingresos1T,
      contrato1T: ctx.contrato1T,
      ingresos2T: ctx.ingresos2T,
      contrato2T: ctx.contrato2T,
    },
    binary: {},
  }];
}

// No usa API externa, no convierte los PDFs a Base64 y no requiere módulos npm.
// Formato: ZIP estándar + ZipCrypto (legacy) + método STORE (sin recomprimir).
// Motivo de STORE: PDFs/JPGs ya suelen venir comprimidos y así evitamos alterar bytes.

const inputItems = $input.all();
if (inputItems.length === 0) {
  throw new Error('No hay archivos binarios para crear el ZIP.');
}

const sourceItems = $('Filtrar documentos C/D').all();
if (sourceItems.length !== inputItems.length) {
  throw new Error(`Descuadre de archivos: ${sourceItems.length} esperados y ${inputItems.length} descargados.`);
}

const ctx = sourceItems[0].json;
const password = String(ctx.dni || '').trim();
if (!password) throw new Error('No hay DNI. No se puede proteger el ZIP con contraseña.');
if (!ctx.zipFilename) throw new Error('No se pudo determinar el nombre del ZIP.');

// ---------- CRC32 ----------
const CRC_TABLE = (() => {
  const table = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) {
      c = (c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1);
    }
    table[n] = c >>> 0;
  }
  return table;
})();

function crc32Byte(crc, byte) {
  return ((crc >>> 8) ^ CRC_TABLE[(crc ^ byte) & 0xff]) >>> 0;
}

function crc32(buffer) {
  let crc = 0xffffffff;
  for (const byte of buffer) crc = crc32Byte(crc, byte);
  return (crc ^ 0xffffffff) >>> 0;
}

// ---------- ZipCrypto ----------
function updateKeys(keys, plainByte) {
  keys[0] = crc32Byte(keys[0], plainByte);
  keys[1] = (keys[1] + (keys[0] & 0xff)) >>> 0;
  keys[1] = (Math.imul(keys[1], 134775813) + 1) >>> 0;
  keys[2] = crc32Byte(keys[2], (keys[1] >>> 24) & 0xff);
}

function initKeys(passwordBytes) {
  const keys = [0x12345678 >>> 0, 0x23456789 >>> 0, 0x34567890 >>> 0];
  for (const byte of passwordBytes) updateKeys(keys, byte);
  return keys;
}

function decryptByte(keys) {
  const temp = (keys[2] | 2) >>> 0;
  return (Math.imul(temp, (temp ^ 1) >>> 0) >>> 8) & 0xff;
}

function encryptZipCrypto(data, passwordBytes, crc) {
  const keys = initKeys(passwordBytes);
  const plain = Buffer.alloc(12 + data.length);

  // 11 bytes aleatorios del encryption header.
  // Math.random es suficiente para la cabecera de ZipCrypto; el algoritmo en sí es legacy.
  for (let i = 0; i < 11; i++) plain[i] = Math.floor(Math.random() * 256);

  // Como conocemos CRC y no usamos data descriptor, el byte de validación es CRC[31:24].
  plain[11] = (crc >>> 24) & 0xff;
  data.copy(plain, 12);

  const encrypted = Buffer.alloc(plain.length);
  for (let i = 0; i < plain.length; i++) {
    const p = plain[i];
    encrypted[i] = p ^ decryptByte(keys);
    updateKeys(keys, p);
  }
  return encrypted;
}

// ---------- Helpers ZIP ----------
function dosDateTime(date = new Date()) {
  const year = Math.max(1980, Math.min(2107, date.getFullYear()));
  const dosTime =
    ((date.getHours() & 0x1f) << 11) |
    ((date.getMinutes() & 0x3f) << 5) |
    (Math.floor(date.getSeconds() / 2) & 0x1f);
  const dosDate =
    (((year - 1980) & 0x7f) << 9) |
    (((date.getMonth() + 1) & 0x0f) << 5) |
    (date.getDate() & 0x1f);
  return { dosTime, dosDate };
}

function uniqueFileName(rawName, usedNames) {
  let name = String(rawName || 'document')
    .replace(/\\/g, '/')
    .split('/')
    .pop()
    .replace(/[\x00-\x1f]/g, '_')
    .trim();

  if (!name) name = 'document';

  const dot = name.lastIndexOf('.');
  const base = dot > 0 ? name.slice(0, dot) : name;
  const ext = dot > 0 ? name.slice(dot) : '';
  let candidate = name;
  let counter = 2;

  while (usedNames.has(candidate.toLowerCase())) {
    candidate = `${base}_${counter++}${ext}`;
  }
  usedNames.add(candidate.toLowerCase());
  return candidate;
}

async function getDownloadedBuffer(itemIndex, item) {
  const binaryKeys = Object.keys(item.binary || {});
  if (binaryKeys.length === 0) {
    throw new Error(`El archivo ${sourceItems[itemIndex]?.json?.fileName || itemIndex + 1} no contiene binary data.`);
  }
  const binaryProperty = item.binary?.data ? 'data' : binaryKeys[0];
  const buffer = await this.helpers.getBinaryDataBuffer(itemIndex, binaryProperty);
  if (!buffer || buffer.length === 0) {
    throw new Error(`El archivo ${sourceItems[itemIndex]?.json?.fileName || itemIndex + 1} está vacío.`);
  }
  return Buffer.from(buffer);
}

const passwordBytes = Buffer.from(password, 'utf8');
const localParts = [];
const centralParts = [];
const usedNames = new Set();
const includedFiles = [];
let localOffset = 0;
let totalSourceBytes = 0;

for (let i = 0; i < inputItems.length; i++) {
  const data = await getDownloadedBuffer.call(this, i, inputItems[i]);
  const src = sourceItems[i]?.json || inputItems[i].json || {};
  const fileName = uniqueFileName(src.fileName || `document_${i + 1}`, usedNames);
  const nameBytes = Buffer.from(fileName, 'utf8');

  if (nameBytes.length > 65535) throw new Error(`Nombre de archivo demasiado largo: ${fileName}`);
  if (data.length > 0xffffffff - 12) throw new Error(`Archivo demasiado grande para ZIP clásico: ${fileName}`);

  const crc = crc32(data);
  const encryptedData = encryptZipCrypto(data, passwordBytes, crc);
  const { dosTime, dosDate } = dosDateTime();

  // Bit 0 = encrypted. Bit 11 = filename UTF-8.
  const flags = 0x0801;
  const compressionMethod = 0; // STORE

  // Local file header (30 bytes)
  const localHeader = Buffer.alloc(30);
  localHeader.writeUInt32LE(0x04034b50, 0);
  localHeader.writeUInt16LE(20, 4); // version needed 2.0
  localHeader.writeUInt16LE(flags, 6);
  localHeader.writeUInt16LE(compressionMethod, 8);
  localHeader.writeUInt16LE(dosTime, 10);
  localHeader.writeUInt16LE(dosDate, 12);
  localHeader.writeUInt32LE(crc, 14);
  localHeader.writeUInt32LE(encryptedData.length, 18);
  localHeader.writeUInt32LE(data.length, 22);
  localHeader.writeUInt16LE(nameBytes.length, 26);
  localHeader.writeUInt16LE(0, 28); // extra length

  localParts.push(localHeader, nameBytes, encryptedData);

  // Central directory header (46 bytes)
  const centralHeader = Buffer.alloc(46);
  centralHeader.writeUInt32LE(0x02014b50, 0);
  centralHeader.writeUInt16LE(20, 4); // version made by
  centralHeader.writeUInt16LE(20, 6); // version needed
  centralHeader.writeUInt16LE(flags, 8);
  centralHeader.writeUInt16LE(compressionMethod, 10);
  centralHeader.writeUInt16LE(dosTime, 12);
  centralHeader.writeUInt16LE(dosDate, 14);
  centralHeader.writeUInt32LE(crc, 16);
  centralHeader.writeUInt32LE(encryptedData.length, 20);
  centralHeader.writeUInt32LE(data.length, 24);
  centralHeader.writeUInt16LE(nameBytes.length, 28);
  centralHeader.writeUInt16LE(0, 30); // extra length
  centralHeader.writeUInt16LE(0, 32); // comment length
  centralHeader.writeUInt16LE(0, 34); // disk start
  centralHeader.writeUInt16LE(0, 36); // internal attrs
  centralHeader.writeUInt32LE(0, 38); // external attrs
  centralHeader.writeUInt32LE(localOffset, 42);

  centralParts.push(centralHeader, nameBytes);
  localOffset += localHeader.length + nameBytes.length + encryptedData.length;
  totalSourceBytes += data.length;
  includedFiles.push({ fileName, sizeBytes: data.length, crc32: crc.toString(16).padStart(8, '0') });
}

if (includedFiles.length > 65535) throw new Error('Demasiados archivos para ZIP clásico.');

const centralDirectory = Buffer.concat(centralParts);
if (localOffset > 0xffffffff || centralDirectory.length > 0xffffffff) {
  throw new Error('ZIP demasiado grande para formato clásico (ZIP64 no está habilitado).');
}

// End of central directory
const eocd = Buffer.alloc(22);
eocd.writeUInt32LE(0x06054b50, 0);
eocd.writeUInt16LE(0, 4);
eocd.writeUInt16LE(0, 6);
eocd.writeUInt16LE(includedFiles.length, 8);
eocd.writeUInt16LE(includedFiles.length, 10);
eocd.writeUInt32LE(centralDirectory.length, 12);
eocd.writeUInt32LE(localOffset, 16);
eocd.writeUInt16LE(0, 20);

const zipBuffer = Buffer.concat([...localParts, centralDirectory, eocd]);

// Sanity checks antes de entregarlo al siguiente nodo.
if (zipBuffer.length < 22 || zipBuffer.readUInt32LE(0) !== 0x04034b50) {
  throw new Error('El ZIP generado no tiene una cabecera ZIP válida.');
}
if (zipBuffer.readUInt32LE(zipBuffer.length - 22) !== 0x06054b50) {
  throw new Error('El ZIP generado no tiene un directorio central válido.');
}

const binaryData = await this.helpers.prepareBinaryData(
  zipBuffer,
  ctx.zipFilename,
  'application/zip'
);

return [{
  json: {
    dealId: ctx.dealId,
    bankDealId: ctx.bankDealId,
    folderId: ctx.folderId,
    zipFilename: ctx.zipFilename,
    nombreCliente: ctx.nombreCliente,
    dni: ctx.dni,
    plan: ctx.plan,
    missingDocs: ctx.missingDocs || [],
    fileCount: includedFiles.length,
    includedFiles,
    totalSourceBytes,
    zipSizeBytes: zipBuffer.length,
    zipCreated: true,
    zipEncryption: 'ZipCrypto',
    zipCompression: 'STORE',
    importeCompraventa: ctx.importeCompraventa,
    importeHipoteca: ctx.importeHipoteca,
    ingresos1T: ctx.ingresos1T,
    contrato1T: ctx.contrato1T,
    ingresos2T: ctx.ingresos2T,
    contrato2T: ctx.contrato2T,
  },
  binary: {
    data: binaryData,
  },
}];

// Construir el link de Drive y preparar datos para Supabase y Rastreator
const zipInfo = $('Crear ZIP cifrado (DNI)').first().json;
const uploadOrExisting = $input.first().json;

// Si se subió un ZIP nuevo, tomar el ID del resultado de upload
// Si se usó uno existente, tomar el ID existente
const zipFileId = uploadOrExisting.id || uploadOrExisting.fileId || zipInfo.existingZipFileId || '';
const zipDriveLink = zipInfo.existingZipDriveLink || (zipFileId
  ? `https://drive.google.com/file/d/${zipFileId}/view`
  : '');

return [{
  json: {
    ...zipInfo,
    zipFileId,
    zipDriveLink,
    skippedUpload: uploadOrExisting.skippedUpload || false,
  }
}];

